 Long source(String kind,String amount){Long id=settlementService.submit(new HrmPayrollTaxSettlementReqVO().setFilingId(filing.getId()).setEmployeeId(employeeId).setMode(filingSource.getRows().get(0).getMode()).setKind(kind).setAmount(n(amount)).setEmployeeAcknowledgement("员工确认税款收退").setEvidence("批准申报依据").setReason("补退税").setRequestKey(UUID.randomUUID().toString()),1L);settlementService.review(id,true,"独立核实税款",2L);settlementId=id;return id;}
 HrmPayrollOffsetReqVO req(Long source){return new HrmPayrollOffsetReqVO().setBatchId(batchId).setEmployeeId(employeeId).setSourceId(source).setSourceType("TAX").setEvidence("指定下一期工资处理").setRequestKey(UUID.randomUUID().toString());}
 Long approve(Long source){Long id=service.create(req(source),3L);service.review(id,true,"核对纳税身份及工资分配",4L);return id;}
 HrmSalaryMonthEmployeeRecordDO calculate(){HrmPayrollTaxCashLedgerVO prior=cash.forApprovedPayrollForBatch(10L,employeeId,2026,YearMonth.from(date()).atEndOfMonth().isAfter(LocalDate.now(ZoneId.of("Asia/Shanghai")))?LocalDate.now(ZoneId.of("Asia/Shanghai")):YearMonth.from(date()).atEndOfMonth(),batchId);assertTrue(prior.isReady(),JsonUtils.toJsonString(prior));List<HrmSalaryOptionValueVO> values=new ArrayList<>();values.add(new HrmSalaryOptionValueVO().setCode(10101).setValue(n("10000")));values.add(new HrmSalaryOptionValueVO().setCode(250101).setValue(prior.getIncome()));values.add(new HrmSalaryOptionValueVO().setCode(250102).setValue(prior.getBasicDeduction()));values.add(new HrmSalaryOptionValueVO().setCode(250103).setValue(prior.getSocialDeduction()));values.add(new HrmSalaryOptionValueVO().setCode(250105).setValue(prior.getWithheld()));HrmSalaryMonthEmployeeRecordDO record=new HrmSalaryMonthEmployeeRecordDO().setMonthRecordId(batchId).setEmployeeId(employeeId).setEntityId(10L).setYear(2026).setMonth(10).setTaxPaymentDate(date()).setFormulaDate(date().withDayOfMonth(1)).setActualWorkDay(n("1")).setNeedWorkDay(n("1"));return calculator.calculateMonthEmployeeRecordList(Collections.singletonList(record),Collections.singletonMap(employeeId,values),Collections.singletonMap(employeeId,taxRule)).get(0);}
 HrmPayrollPaymentDO payment(HrmSalaryMonthEmployeeRecordDO result,String status){HrmPayrollRunDO run=new HrmPayrollRunDO().setMonthRecordId(batchId).setVersion(1).setInputSnapshot(JsonUtils.toJsonString(Collections.singletonMap("settlementOffsets",service.sources(batchId,5L)))).setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(result)));runs.insert(run);batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(16));HrmPayrollPaymentDO p=new HrmPayrollPaymentDO().setMonthRecordId(batchId).setRunId(run.getId()).setEmployeeId(employeeId).setEmployeeName("退补税员工").setBankAccount("test-only").setAmount(result.getRealPaySalary()).setStatus(status).setAttempt(1).setValueDate("SUCCESS".equals(status)?LocalDate.now(ZoneId.of("Asia/Shanghai")):null);payments.insert(p);return p;}
 @Test void sameYearRecoveryChangesPlannedBaselineAndDoesNotDoubleCollect(){Long source=source("RECOVERY","50"),offset=approve(source);assertFalse(cash.forApprovedPayroll(10L,employeeId,2026,date()).isReady());HrmPayrollTaxCashLedgerVO planned=cash.forApprovedPayrollForBatch(10L,employeeId,2026,date(),batchId);assertEquals(0,n("150").compareTo(planned.getWithheld()));assertTrue(planned.getRows().stream().anyMatch(row->"APPROVED_PAYROLL_OFFSET".equals(row.getStatus())));HrmSalaryMonthEmployeeRecordDO result=calculate();assertEquals(0,n("10000").compareTo(result.getExpectedPaySalary()));assertEquals(0,n("150").compareTo(result.getPersonalTax()));assertEquals(0,n("9800").compareTo(result.getRealPaySalary()));HrmPayrollPaymentDO paid=payment(result,"SUCCESS");service.consume(paid.getId(),5L);service.consume(paid.getId(),5L);assertEquals("CONSUMED",offsets.selectById(offset).getStatus());assertEquals("SETTLED",settlements.selectById(source).getStatus());HrmPayrollTaxCashLedgerVO actual=cash.forApprovedPayroll(10L,employeeId,2026,LocalDate.now(ZoneId.of("Asia/Shanghai")));assertTrue(actual.isReady());assertEquals(0,n("300").compareTo(actual.getWithheld()));assertEquals(0,n("20000").compareTo(actual.getIncome()));assertTrue(actual.getRows().stream().noneMatch(row->"APPROVED_PAYROLL_OFFSET".equals(row.getStatus())));}
 @Test void sameYearRefundRestoresBaselineBeforeCurrentWithholdingAndPaysOnlyOnce(){profile.setOpeningIncome(n("6666.67"));profileMapper.updateById(profile);filingSource.getRows().get(0).setExpectedSalaryWithholding(n("50"));filings.updateById(new HrmPayrollTaxFilingDO().setId(filing.getId()).setSourceSnapshot(JsonUtils.toJsonString(filingSource)));Long source=source("REFUND","50");approve(source);assertEquals(0,n("50").compareTo(cash.forApprovedPayrollForBatch(10L,employeeId,2026,date(),batchId).getWithheld()));HrmSalaryMonthEmployeeRecordDO result=calculate();assertEquals(0,n("150").compareTo(result.getPersonalTax()));assertEquals(0,n("9900").compareTo(result.getRealPaySalary()));HrmPayrollPaymentDO p=payment(result,"SUCCESS");service.consume(p.getId(),5L);assertEquals(0,n("200").compareTo(cash.forApprovedPayroll(10L,employeeId,2026,LocalDate.now(ZoneId.of("Asia/Shanghai"))).getWithheld()));}
 @Test void pendingAndChangedSourcesBlockComputationAndExternalCashCannotDoubleSettle(){Long source=source("RECOVERY","50"),id=service.create(req(source),3L);assertEquals(5,batches.selectById(batchId).getStatus());assertServiceException(()->service.assertReady(batchId),PAYROLL_OFFSET_INVALID);assertServiceException(()->settlementService.confirm(new HrmPayrollTaxSettlementConfirmReqVO().setId(source).setAmount(n("50")).setValueDate(LocalDate.now(ZoneId.of("Asia/Shanghai"))).setBankReference("external-duplicate").setEvidence("不能重复外部收取"),5L),PAYROLL_OFFSET_INVALID);assertServiceException(()->settlementService.cancel(source,"不能同时撤销税款","作废",5L),PAYROLL_OFFSET_INVALID);service.review(id,true,"核实",4L);when(filingService.detail(anyLong(),anyLong())).thenReturn(Collections.singletonMap("sourceFresh",false));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.values(batchId,employeeId,5L));}
 @Test void failedBankLeavesApprovedTaxAndRetryConsumesOnlyAfterSuccess(){Long source=source("RECOVERY","50"),id=approve(source);HrmPayrollPaymentDO p=payment(calculate(),"FAILED");assertServiceException(()->service.consume(p.getId(),5L),PAYROLL_OFFSET_INVALID);assertEquals("APPROVED",settlements.selectById(source).getStatus());payments.updateById(new HrmPayrollPaymentDO().setId(p.getId()).setStatus("SUCCESS").setValueDate(LocalDate.now(ZoneId.of("Asia/Shanghai"))));service.consume(p.getId(),5L);assertEquals(p.getId(),offsets.selectById(id).getConsumedPaymentId());assertEquals("PAYROLL:"+p.getId()+":"+source,settlements.selectById(source).getBankReference());}
 @Test void independentReviewIdentityAndRequestDedupeAreEnforced(){Long source=source("RECOVERY","50");HrmPayrollOffsetReqVO request=req(source);Long id=service.create(request,3L);assertEquals(id,service.create(request,3L));assertServiceException(()->service.create(req(source),3L),PAYROLL_OFFSET_INVALID);assertServiceException(()->service.review(id,true,"创建人",3L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.review(id,true,"员工本人",99L),PAYROLL_SELF_APPROVAL);profile.setTaxpayerKey("another-person");assertServiceException(()->service.review(id,true,"错误身份",4L),PAYROLL_OFFSET_INVALID);}
