 @Test void zeroNetWageNeedsExplicitZeroSettlementProofBeforeConsumingTaxOffset(){filingSource.getRows().get(0).setMode("SEPARATE_BONUS").setWithheld(BigDecimal.ZERO).setExpectedBonusWithholding(n("9800"));filings.updateById(new HrmPayrollTaxFilingDO().setId(filing.getId()).setSourceSnapshot(JsonUtils.toJsonString(filingSource)));Long source=source("RECOVERY","9800");approve(source);HrmSalaryMonthEmployeeRecordDO result=calculate();assertEquals(0,BigDecimal.ZERO.compareTo(result.getRealPaySalary()));assertEquals(0,n("200").compareTo(result.getPersonalTax()));HrmPayrollPaymentDO p=payment(result,"SUCCESS");assertServiceException(()->service.consume(p.getId(),5L),PAYROLL_OFFSET_INVALID);payments.updateById(new HrmPayrollPaymentDO().setId(p.getId()).setZeroSettlementReference("explicit-zero-offset").setZeroSettlementEvidence("已核实零实发工资，非银行转账"));service.consume(p.getId(),5L);assertEquals("SETTLED",settlements.selectById(source).getStatus());assertTrue(settlements.selectById(source).getBankEvidence().contains("零实发核实"));}
 @Test void priorYearTaxRefundDoesNotChangeCurrentYearTaxBaseline(){HrmPayrollTaxProfileDO old=JsonUtils.parseObject(JsonUtils.toJsonString(profile),HrmPayrollTaxProfileDO.class).setId(null).setYear(2025);old.setTaxpayerKey("same-person");profileMapper.insert(old);filingSource.setYear(2025).setMonth(12);filingSource.getRows().get(0).setProfileId(old.getId()).setExpectedSalaryWithholding(n("50"));filings.updateById(new HrmPayrollTaxFilingDO().setId(filing.getId()).setYear(2025).setMonth(12).setSourceSnapshot(JsonUtils.toJsonString(filingSource)));Long source=source("REFUND","50"),id=approve(source);assertEquals(2025,settlements.selectById(source).getYear());assertEquals(0,n("100").compareTo(cash.forApprovedPayrollForBatch(10L,employeeId,2026,date(),batchId).getWithheld()));HrmSalaryMonthEmployeeRecordDO result=calculate();assertEquals(0,n("200").compareTo(result.getPersonalTax()));assertEquals(0,n("9850").compareTo(result.getRealPaySalary()));HrmPayrollPaymentDO p=payment(result,"SUCCESS");service.consume(p.getId(),5L);assertEquals("CONSUMED",offsets.selectById(id).getStatus());assertEquals(2025,settlements.selectById(source).getYear());assertEquals(LocalDate.now(ZoneId.of("Asia/Shanghai")),settlements.selectById(source).getValueDate());assertEquals(0,n("300").compareTo(cash.forApprovedPayroll(10L,employeeId,2026,LocalDate.now(ZoneId.of("Asia/Shanghai"))).getWithheld()));}
 @Test void onlyDesignatedBatchCanUsePlannedTaxAndFrozenAssignmentsCannotBeCancelled(){Long source=source("RECOVERY","50"),id=approve(source);HrmSalaryMonthRecordDO other=new HrmSalaryMonthRecordDO().setEntityId(10L).setBatchKey("REGULAR").setYear(2026).setMonth(11).setStatus(5).setExpectedPaymentDate(LocalDate.of(2026,11,15));batches.insert(other);assertFalse(cash.forApprovedPayrollForBatch(10L,employeeId,2026,date(),other.getId()).isReady());List<HrmPayrollOffsetService.Source> snapshot=service.sources(batchId,5L);String input=JsonUtils.toJsonString(Collections.singletonMap("settlementOffsets",snapshot));service.validateInputSnapshot(input,batchId,5L);batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(15));assertServiceException(()->service.cancel(id,"冻结不能撤销",3L),PAYROLL_OFFSET_INVALID);settlements.updateById(new HrmPayrollTaxSettlementDO().setId(source).setAmount(n("49")));assertThrows(cn.iocoder.yudao.framework.common.exception.ServiceException.class,()->service.validateInputSnapshot(input,batchId,5L));}
 @Test void rehireCanSettleAnOldEmployeeRecordForTheSameTaxpayerButBothUsersAvoidReview(){Long source=source("RECOVERY","50");HrmEmployeeDO next=new HrmEmployeeDO().setName("重新入职员工").setUserId(199L);employees.insert(next);when(inputs.roster(any())).thenReturn(Collections.singletonList(next));when(scope.payrollDates(any())).thenReturn(Collections.singletonMap(next.getId(),Collections.singleton(date())));when(groups.getEmployeeSalaryGroupMap(anyList())).thenReturn(Collections.singletonMap(next.getId(),new HrmSalaryGroupDO().setId(13L).setTaxRuleId(14L)));HrmPayrollTaxProfileDO current=JsonUtils.parseObject(JsonUtils.toJsonString(profile),HrmPayrollTaxProfileDO.class).setId(null).setEmployeeId(next.getId());current.setTaxpayerKey("same-person");profileMapper.insert(current);when(profiles.requireApproved(10L,next.getId(),2026)).thenReturn(current);Long id=service.create(req(source).setEmployeeId(next.getId()),3L);assertServiceException(()->service.review(id,true,"旧账号本人",99L),PAYROLL_SELF_APPROVAL);assertServiceException(()->service.review(id,true,"新账号本人",199L),PAYROLL_SELF_APPROVAL);service.review(id,true,"独立核实同一纳税身份",4L);assertEquals(next.getId(),offsets.selectById(id).getEmployeeId());assertEquals(employeeId,settlements.selectById(source).getEmployeeId());}
