 @Test void crossYearOffsetFreezesBothTaxYearsAndKeepsClaimsStableAfterPartialLifecycle(){
  HrmPayrollTaxProfileDO old=JsonUtils.parseObject(JsonUtils.toJsonString(profile),HrmPayrollTaxProfileDO.class).setId(null).setYear(2025);old.setTaxpayerKey("same-person");profileMapper.insert(old);filingSource.setYear(2025).setMonth(12);filingSource.getRows().get(0).setProfileId(old.getId()).setExpectedSalaryWithholding(n("50"));filings.updateById(new HrmPayrollTaxFilingDO().setId(filing.getId()).setYear(2025).setMonth(12).setSourceSnapshot(JsonUtils.toJsonString(filingSource)));Long source=source("REFUND","50");approve(source);HrmSalaryMonthEmployeeRecordDO result=calculate();
  Map<String,Object> overtime=new LinkedHashMap<>();overtime.put("entries",Collections.emptyList());overtime.put("cycles",Collections.emptyList());
  legalEntities.insert(new HrmPayrollLegalEntityDO().setId(10L).setName("工资法人").setStatus("APPROVED"));Map<String,Object> input=new LinkedHashMap<>();input.put("settlementOffsets",service.sources(batchId,5L));input.put("withholdingContexts",Collections.singletonList(result.getTaxSourceSnapshot()));input.put("entityPayrollDates",Collections.singletonMap(employeeId,Collections.singleton(date())));input.put("approvedInputs",Collections.singletonMap(employeeId,Collections.singletonMap("OVERTIME",new HrmPayrollInputDO().setSourceSnapshot(JsonUtils.toJsonString(overtime)))));input.put("insurancePolicySources",Collections.singletonMap(employeeId,new HrmPayrollInsurancePolicyService.Quote().setEmployeeId(employeeId).setEntityId(10L).setCoverage("EXEMPT")));
  HrmPayrollRunDO run=new HrmPayrollRunDO().setMonthRecordId(batchId).setVersion(1).setInputSnapshot(JsonUtils.toJsonString(input)).setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(result)));runs.insert(run);batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(15));sourceClaims.reserve(batches.selectById(batchId),run,5L);List<HrmPayrollSourceClaimDO> claims=sourceClaims.list(batchId,5L);assertEquals(2,claims.stream().filter(row->"TAX_YEAR".equals(row.getKind())).count());assertEquals(1,claims.stream().filter(row->"SETTLEMENT_OFFSET".equals(row.getKind())).count());assertTrue(claims.stream().anyMatch(row->row.getSourceKey().startsWith(cn.hutool.crypto.digest.DigestUtil.sha256Hex("10:same-person:2025"))));sourceClaims.assertReserved(batchId,run.getId());
  HrmPayrollPaymentDO p=new HrmPayrollPaymentDO().setMonthRecordId(batchId).setRunId(run.getId()).setEmployeeId(employeeId).setEmployeeName("退补税员工").setBankAccount("test-only").setAmount(result.getRealPaySalary()).setStatus("SUCCESS").setAttempt(1).setValueDate(LocalDate.now(ZoneId.of("Asia/Shanghai")));payments.insert(p);batches.updateById(new HrmSalaryMonthRecordDO().setId(batchId).setStatus(16));sourceClaims.paid(batchId,run.getId(),employeeId);service.consume(p.getId(),5L);sourceClaims.assertReserved(batchId,run.getId());assertTrue(sourceClaims.list(batchId,5L).stream().allMatch(row->"PAID".equals(row.getStatus())));
 }

