  HrmSalaryMonthEmployeeRecordDO wage=new HrmSalaryMonthEmployeeRecordDO().setEmployeeId(employeeId).setExpectedPaySalary(n("10000")).setRealPaySalary(n("8900")).setPersonalTax(n("100")).setOptionValues(values).setTaxSourceSnapshot(JsonUtils.toJsonString(source));
  HrmPayrollRunDO run=new HrmPayrollRunDO().setMonthRecordId(b.getId()).setVersion(1).setInputSnapshot(JsonUtils.toJsonString(Collections.singletonMap("insurancePolicySources",Collections.singletonMap(employeeId,q)))).setRuleSnapshot("{}").setResultSnapshot(JsonUtils.toJsonString(Collections.singletonList(wage)));runs.insert(run);
