  HrmPayrollTaxCorrectionDO c=new HrmPayrollTaxCorrectionDO().setEntityId(10L).setEmployeeId(employeeId).setPaymentId(p.getId()).setRunId(run.getId()).setVersion(1).setPolicyId(policy.getId()).setPolicyVersion(1).setProfileId(profile.getId()).setProfileVersion(1).setTaxpayerKey(profile.getTaxpayerKey()).setTaxRegistrationNumber("agent").setIncome(n("10000")).setSocialDeduction(n(personal)).setBasicDeduction(n("5000")).setActualSalaryWithheld(n("100")).setActualBonusWithheld(BigDecimal.ZERO).setSeparateBonusIncome(BigDecimal.ZERO).setValueDate(p.getValueDate()).setSourceDigest(HrmPayrollTaxCorrectionService.digest(p,run)).setStatus("APPROVED").setRequestSnapshot(JsonUtils.toJsonString(new HrmPayrollTaxCorrectionReqVO().setOpeningAlreadyIncludesCorrection(true)));taxCorrections.insert(c);
  profile.setOpeningSocialDeduction(n(personal));profileMapper.updateById(profile);
